ALTER TABLE `a365-de-ignacio.assist365_control.ingestion_runs` SET OPTIONS (description = "Esta tabla registra en BigQuery el ciclo de vida y el resultado operativo de cada ejecución de extracción. Permite medir solicitudes y reintentos, conocer los watermarks observados y consultar el resumen de procesamiento para demostrar qué se intentó cargar, detectar ejecuciones incompletas y comparar corridas sin depender de logs efímeros de la máquina.");
ALTER TABLE `a365-de-ignacio.assist365_control.ingestion_runs` ALTER COLUMN run_id SET OPTIONS (description = "Identificador de la corrida de extracción de origen.");
