ALTER TABLE `a365-de-ignacio.assist365_control.ingestion_errors` SET OPTIONS (description = "Esta tabla centraliza en BigQuery los errores asociados a registros o etapas de extracción, con referencias para volver al recurso, lote, página, archivo y ejecución que los originó. Sirve como cola auditable de investigación y resolución: cada falla debe quedar identificada, clasificable y vinculada a su estado de tratamiento, evitando que errores individuales queden ocultos en un resultado agregado.");
ALTER TABLE `a365-de-ignacio.assist365_control.ingestion_errors` ALTER COLUMN created_at SET OPTIONS (description = "Fecha UTC en que se registró el error de extracción.");
