ALTER TABLE `a365-de-ignacio.assist365_control.reconciliations` SET OPTIONS (description = "Esta tabla almacena en BigQuery los resultados de controles de integridad y reconciliación ejecutados sobre cada recurso y corrida. Sus conteos esperados, observados y diferencias permiten confirmar explícitamente si una extracción o proceso fue completo; el detalle JSON conserva evidencia diagnóstica para investigar discrepancias sin escanear nuevamente los datos de origen.");
ALTER TABLE `a365-de-ignacio.assist365_control.reconciliations` ALTER COLUMN checked_at SET OPTIONS (description = "Fecha UTC en que se ejecutó el control de calidad.");
