ALTER TABLE `a365-de-ignacio.assist365_control.reconciliations` ALTER COLUMN check_status SET OPTIONS (description = "Resultado del control: PASS, FAIL, BLOCKED, REVIEW o INFO.");
ALTER TABLE `a365-de-ignacio.assist365_control.reconciliations` ALTER COLUMN expected_count SET OPTIONS (description = "Cantidad de referencia esperada por este control.");
ALTER TABLE `a365-de-ignacio.assist365_control.reconciliations` ALTER COLUMN actual_count SET OPTIONS (description = "Cantidad observada al ejecutar el control de calidad.");
ALTER TABLE `a365-de-ignacio.assist365_control.reconciliations` ALTER COLUMN difference_count SET OPTIONS (description = "Diferencia entre el conteo observado y el esperado.");
