ALTER TABLE `a365-de-ignacio.assist365_control.watermarks` SET OPTIONS (description = "Esta tabla mantiene en BigQuery el punto de avance confirmado por recurso para orientar las siguientes cargas incrementales. El watermark solo debe avanzar tras completar las validaciones de la corrida asociada; el margen de solapamiento facilita recuperar cambios tardíos y su historial permite auditar qué ejecución comprometió cada posición de lectura.");
ALTER TABLE `a365-de-ignacio.assist365_control.watermarks` ALTER COLUMN resource SET OPTIONS (description = "Recurso de la API al que pertenece el registro.");
