ALTER TABLE `a365-de-ignacio.assist365_control.watermarks` ALTER COLUMN overlap_seconds SET OPTIONS (description = "Segundos de solapamiento usados en la lectura delta.");
ALTER TABLE `a365-de-ignacio.assist365_control.snapshot_diffs` SET OPTIONS (description = "Esta tabla conserva en BigQuery las diferencias calculadas entre snapshots sucesivos, incluyendo claves presentes, hashes comparados y estado de revisión. Se usa para detectar altas, modificaciones y posibles ausencias que requieren análisis; una ausencia no se interpreta automáticamente como baja y cada diferencia queda disponible para revisión y trazabilidad.");
ALTER TABLE `a365-de-ignacio.assist365_control.snapshot_diffs` ALTER COLUMN compared_at SET OPTIONS (description = "Fecha UTC en que se compararon las dos capturas.");
ALTER TABLE `a365-de-ignacio.assist365_control.snapshot_diffs` ALTER COLUMN resource SET OPTIONS (description = "Recurso de la API al que pertenece el registro.");
ALTER TABLE `a365-de-ignacio.assist365_control.snapshot_diffs` ALTER COLUMN previous_snapshot_id SET OPTIONS (description = "Identificador de la captura anterior de comparación.");
ALTER TABLE `a365-de-ignacio.assist365_control.snapshot_diffs` ALTER COLUMN current_snapshot_id SET OPTIONS (description = "Identificador de la captura actual de comparación.");
ALTER TABLE `a365-de-ignacio.assist365_control.snapshot_diffs` ALTER COLUMN source_key SET OPTIONS (description = "Clave de origen usada para localizar la fila raw.");
ALTER TABLE `a365-de-ignacio.assist365_control.snapshot_diffs` ALTER COLUMN change_type SET OPTIONS (description = "Cambio observado: alta, modificación o ausencia a revisar.");
